import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), sr = nextInt(), sc = nextInt();
        long[] h = new long[n * m];
        for (int i = 0; i < n * m; i++) h[i] = nextLong();
        int[] dist = new int[n * m], q = new int[n * m];
        java.util.Arrays.fill(dist, -1);
        int qh = 0, qt = 0;
        dist[sr * m + sc] = 0;
        q[qt++] = sr * m + sc;
        int[] di = {-1, 1, 0, 0}, dj = {0, 0, -1, 1};
        while (qh < qt) {
            int cur = q[qh++], i = cur / m, j = cur % m;
            for (int d = 0; d < 4; d++) {
                int a = i + di[d], b = j + dj[d];
                // Water flows only to neighbors that are not higher.
                if (a >= 0 && a < n && b >= 0 && b < m && dist[a * m + b] < 0 && h[a * m + b] <= h[cur]) {
                    dist[a * m + b] = dist[cur] + 1;
                    q[qt++] = a * m + b;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) sb.append(dist[i * m + j]).append(j + 1 < m ? ' ' : '\n');
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        pw.print(sb);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n, m, sr, sc := readInt(), readInt(), readInt(), readInt()
	h := make([]int, n*m)
	for i := range h {
		h[i] = readInt()
	}
	dist := make([]int, n*m)
	for i := range dist {
		dist[i] = -1
	}
	q := make([]int, 0, n*m)
	dist[sr*m+sc] = 0
	q = append(q, sr*m+sc)
	di := [4]int{-1, 1, 0, 0}
	dj := [4]int{0, 0, -1, 1}
	for k := 0; k < len(q); k++ {
		cur := q[k]
		i, j := cur/m, cur%m
		for d := 0; d < 4; d++ {
			a, b := i+di[d], j+dj[d]
			// Water flows only to neighbors that are not higher.
			if a >= 0 && a < n && b >= 0 && b < m && dist[a*m+b] < 0 && h[a*m+b] <= h[cur] {
				dist[a*m+b] = dist[cur] + 1
				q = append(q, a*m+b)
			}
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	buf := make([]byte, 0, 16)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			buf = strconv.AppendInt(buf[:0], int64(dist[i*m+j]), 10)
			w.Write(buf)
			if j+1 < m {
				w.WriteByte(' ')
			} else {
				w.WriteByte('\n')
			}
		}
	}
}
